import{_ as e,o as i,c as a,ag as s}from"./chunks/framework.D9ghT4bC.js";const c=JSON.parse('{"title":"Map-related JSON files","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Mod-file-structure/3-Map-related-JSON-files.md","filePath":"Modders/Mod-file-structure/3-Map-related-JSON-files.md"}'),n={name:"Modders/Mod-file-structure/3-Map-related-JSON-files.md"};function r(o,t,d,l,h,u){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="map-related-json-files" tabindex="-1">Map-related JSON files <a class="header-anchor" href="#map-related-json-files" aria-label="Permalink to &quot;Map-related JSON files&quot;">​</a></h1><h2 id="terrains-json" tabindex="-1">Terrains.json <a class="header-anchor" href="#terrains-json" aria-label="Permalink to &quot;Terrains.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/Terrains.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains the base terrains, terrain features and natural wonders that can appear on the map.</p><p>Each terrain entry has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>[^A]</td></tr><tr><td>type</td><td>Enum</td><td>Required</td><td>Land, Water, TerrainFeature, NaturalWonder [^B]</td></tr><tr><td>occursOn</td><td>List of Strings</td><td>none</td><td>Only for terrain features and Natural Wonders: The baseTerrain it can be placed on</td></tr><tr><td>turnsInto</td><td>String</td><td>none</td><td>Only for NaturalWonder: optional mandatory base terrain [^C]</td></tr><tr><td>weight</td><td>Integer</td><td>10</td><td>Only for NaturalWonder: <em>relative</em> weight of being picked by the map generator</td></tr><tr><td><a href="#general-stat"><code>&lt;stats&gt;</code></a></td><td>Float</td><td>0</td><td>Per-turn yield or bonus yield for the tile</td></tr><tr><td>overrideStats</td><td>Boolean</td><td>false</td><td>If true, a feature&#39;s yields replace any yield from underlying terrain instead of adding to it</td></tr><tr><td>unbuildable</td><td>Boolean</td><td>false</td><td>If true, nothing can be built here - not even resource improvements</td></tr><tr><td>impassable</td><td>Boolean</td><td>false</td><td>No unit can enter unless it has a special unique</td></tr><tr><td>movementCost</td><td>Integer</td><td>1</td><td>Base movement cost</td></tr><tr><td>defenceBonus</td><td>Float</td><td>0</td><td>Combat bonus for units being attacked here</td></tr><tr><td>RGB</td><td><a href="./5-Miscellaneous-JSON-files.html#rgb-colors-list">List of 3× Integer</a></td><td>Gold</td><td>RGB color for &#39;Default&#39; tileset display</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this terrain has</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><p>[^A]: Some names have special meanings. <code>Grassland</code> is used as fallback in some cases - e.g. Civilopedia prefers to displays a TerrainFeature on top of it, unless <code>occursOn</code> is not empty and does not contain it. <code>River</code> is hardcoded to be used to look up a <a href="./../uniques.html#global-uniques">Stats</a> unique to determine the bonuses an actual River provides (remember, rivers live on the edges not as terrain). River should always be a TerrainFeature and have the same uniques the one in the vanilla rulesets has - if you change that, expect surprises. [^B]: A base ruleset mod is always expected to provide at least one Land and at least one Water terrain. We do not support Land-only or Water-only mods, even if they might be possible to pull off. [^C]: If set, the base terrain is changed to this after placing the Natural Wonder, and terrain features cleared. Otherwise, terrain features are reduced to only those present in occursOn.</p><h2 id="tileimprovements-json" tabindex="-1">TileImprovements.json <a class="header-anchor" href="#tileimprovements-json" aria-label="Permalink to &quot;TileImprovements.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/TileImprovements.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file lists the improvements that can be constructed or created on a map tile by a unit having the appropriate unique.</p><p>Note that improvements have two visual representations - icon and pixel graphic in the tileset. Omitting the icon results in a horribly ugly user interface, while omitting tileset graphics will just miss out on an <em>optional</em> visualization. If you provide a pixel graphic for FantasyHex, please be aware of the layering system and the ruleVariants in the tileset json. A single graphic may suffice if it has lots of transparency, as it will be drawn on top of all other terrain elements.</p><p>Each improvement has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>[^A]</td></tr><tr><td>terrainsCanBeBuiltOn</td><td>List of Strings</td><td>empty</td><td>Terrains that this improvement can be built on [^B]. Removable terrain features will need to be removed before building an improvement [^C]. Must be in <a href="#terrains-json">Terrains.json</a></td></tr><tr><td>techRequired</td><td>String</td><td>none</td><td>The name of the technology required to build this improvement</td></tr><tr><td>replaces</td><td>String</td><td>none</td><td>The name of a improvement that should be replaced by this improvement. Must be in <a href="#tileimprovements-json">TileImprovements.json</a></td></tr><tr><td>uniqueTo</td><td>String</td><td>none</td><td>The name of the nation this improvement is unique for</td></tr><tr><td><a href="#stats"><code>&lt;stats&gt;</code></a></td><td>Integer</td><td>0</td><td>Per-turn bonus yield for the tile</td></tr><tr><td>turnsToBuild</td><td>Integer</td><td>-1</td><td>Number of turns a worker spends building this. If -1, the improvement is unbuildable [^D]. If 0, the improvement is always built in one turn</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this improvement has</td></tr><tr><td>shortcutKey</td><td>String</td><td>none</td><td>Keyboard binding. Currently, only a single character is allowed (no function keys or Ctrl combinations)</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><p>[^A]: Special improvements: Road, Railroad, Remove *, Cancel improvement order, City ruins, City center, Barbarian encampment - these have special meanings hardcoded to their names. [^B]: Improvements with an empty <code>terrainsCanBeBuiltOn</code> list and positive <code>turnsToBuild</code> value can only be built on <a href="#tileresources-json">resources</a> with <code>improvedBy</code> or <code>improvement</code> that contains the corresponding improvement. [^C]: The removal of terrain features is optional if the feature is named in <code>terrainsCanBeBuiltOn</code> <em>or</em> the unique <code>Does not need removal of [tileFilter]</code> is used (e.g. Camp allowed by resource). [^D]: They can still be created with the UnitAction unique <code>Can instantly construct a [improvementFilter] improvement</code>.</p><h2 id="tileresources-json" tabindex="-1">TileResources.json <a class="header-anchor" href="#tileresources-json" aria-label="Permalink to &quot;TileResources.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/TileResources.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file lists the resources that a map tile can have.</p><p>Note the predefined <code>resourceType</code> enum cannot be altered in a json.</p><p>Note also that resources have two visual representations - icon and pixel graphic in the tileset. Omitting the icon results in a horribly ugly user interface, while omitting tileset graphics will miss out on a visualization on the map. If you provide a pixel graphic for FantasyHex, please be aware of the layering system and the ruleVariants in the tileset json. A single graphic may suffice if it has lots of transparency, as it will be drawn on top of terrain and features but below an improvement - if the single improvement graphic exists at all.</p><p>Each resource has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>resourceType</td><td>Enum</td><td>Bonus</td><td>Bonus, Luxury or Strategic</td></tr><tr><td>terrainsCanBeFoundOn</td><td>List of Strings</td><td>empty</td><td>Terrains that this resource can be found on. Must be in <a href="#terrains-json">Terrains.json</a></td></tr><tr><td><a href="#stats"><code>&lt;stats&gt;</code></a></td><td>Integer</td><td>0</td><td>Per-turn bonus yield for the tile</td></tr><tr><td>improvementStats</td><td>Object</td><td>none</td><td>The additional yield when improved, see <a href="./3-Map-related-JSON-files.html#specialized-stats">specialized stats</a></td></tr><tr><td>revealedBy</td><td>String</td><td>none</td><td>The technology name required to see, work and improve this resource</td></tr><tr><td>improvedBy</td><td>List of strings</td><td>empty</td><td>The improvements required for obtaining this resource. Must be in <a href="#tileimprovements-json">TileImprovements.json</a></td></tr><tr><td>improvement</td><td>String</td><td>none</td><td>The improvement required to obtain this resource. Must be in <a href="#tileimprovements-json">TileImprovements.json</a> (redundant due to <code>improvedBy</code>)</td></tr><tr><td>unique</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this resource has</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h2 id="ruins-json" tabindex="-1">Ruins.json <a class="header-anchor" href="#ruins-json" aria-label="Permalink to &quot;Ruins.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/Ruins.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This optional file contains the possible rewards ancient ruins give.</p><p>Base ruleset Mods can omit the file, in which case they inherit the ones from the Vanilla ruleset. They can, however, provide a file with an empty list (<code>[]</code>) to avoid that. In this case there should be no improvements with the <a href="./../uniques.html#improvement-uniques">&quot;Provides a random bonus when entered&quot; Unique</a>. Conversely, if there are such improvements, the Mod checker will flag an empty Ruins file as error.</p><p>Each of the objects in the file represents a single reward you can get from ruins. It has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Name of the ruins. Never shown to the user, but they have to be distinct</td></tr><tr><td>notification</td><td>String</td><td>Required</td><td>Notification added to the user when this reward is chosen. If omitted, an empty notification is shown. Some notifications may have parameters, refer to the table below.</td></tr><tr><td>weight</td><td>Integer (≥0)</td><td>1</td><td><em>Relative</em> weight this reward is chosen next [^E]</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> that will trigger when entering the ruins. If more than 1 unique is added, the notification will be shown multiple times due to a bug (may be outdated)</td></tr><tr><td>excludedDifficulties</td><td>List of Strings</td><td>empty</td><td>A list of all difficulties on which this reward may <em>not</em> be awarded</td></tr></tbody></table><p>[^E]: The exact algorithm for choosing a reward is the following:</p><ul><li>Create a list of all possible rewards. Each reward&#39;s frequency in the list corresponds to its weight, a reward with weight one will appear once, a reward with weight two will appear twice, etc.</li><li>Shuffle this list</li><li>Try give rewards starting from the top of the list. If any of the uniques of the rewards is valid in this context, reward it and stop trying more rewards.</li></ul><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><p>Some of the rewards ruins can give will have results that are not deterministic when writing it in the JSON, so creating a good notification for it would be impossible. An example for this would be the &quot;Gain [50]-[100] [Gold]&quot; unique, which will give a random amount of gold. For this reason, we allow some notifications to have parameters, in which values will be filled, such as &quot;You found [goldAmount] gold in the ruins!&quot;. All the uniques which have this property can be found below.</p><table tabindex="0"><thead><tr><th>Unique</th><th>Parameters</th></tr></thead><tbody><tr><td>Free [] found in the ruins</td><td>The name of the unit will be filled in the notification, including unique units of the nation</td></tr><tr><td>[] population in a random city</td><td>The name of the city to which the population is added will be filled in the notification</td></tr><tr><td>Gain []-[] []</td><td>The exact amount of the stat gained will be filled in the notification</td></tr><tr><td>[] free random reasearchable Tech(s) from the []</td><td>The notification must have placeholders equal to the number of techs granted this way. Each of the names of these free techs will be filled in the notification</td></tr><tr><td>Gain enough Faith for a Pantheon</td><td>The amount of faith gained is filled in the notification</td></tr><tr><td>Gain enough Faith for []% of a Great Prophet</td><td>The amount of faith gained is filled in the notification</td></tr></tbody></table><h3 id="specific-uniques" tabindex="-1">Specific uniques <a class="header-anchor" href="#specific-uniques" aria-label="Permalink to &quot;Specific uniques&quot;">​</a></h3><p>A few uniques can be added to ancient ruin effects to modify when they can be earned. These are:</p><ul><li>&quot;Only available after [amount] turns&quot;</li><li>&quot;Only available <code>&lt;when religion is enabled&gt;</code>&quot;</li><li>&quot;Hidden after a great prophet has been earned&quot;</li></ul><h2 id="tileset-specific-json" tabindex="-1"><a href="./../Creating-a-custom-tileset.html">Tileset-specific json</a> <a class="header-anchor" href="#tileset-specific-json" aria-label="Permalink to &quot;[Tileset-specific json](../Creating-a-custom-tileset.md)&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/TileSets/FantasyHex.json" target="_blank" rel="noreferrer">Link to original FantasyHex</a></p><p>A mod can define new Tilesets or add to existing ones, namely FantasyHex. There is one json file per Tileset, named same as the Tileset, and placed in a subfolder named &quot;TileSets&quot; relative to the other json files. This is called TileSetConfig and has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><a href="./../Creating-a-custom-tileset.html#usecolorasbaseterrain">useColorAsBaseTerrain</a></td><td>Boolean</td><td>false</td><td></td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#usesummaryimages">useSummaryImages</a></td><td>Boolean</td><td>false</td><td></td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#unexploredtilecolor">unexploredTileColor</a></td><td>Color</td><td>Dark Gray</td><td><code>{&quot;r&quot;:0.25,&quot;g&quot;:0.25,&quot;b&quot;:0.25,&quot;a&quot;:1}</code></td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#fogofwarcolor">fogOfWarColor</a></td><td>Color</td><td>Black</td><td><code>{&quot;r&quot;:0,&quot;g&quot;:0,&quot;b&quot;:0,&quot;a&quot;:1}</code></td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#fallbacktileset">fallbackTileSet</a></td><td>String</td><td>&quot;FantasyHex&quot;</td><td>null to disable</td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#tilescale">tileScale</a></td><td>Float</td><td>1.0</td><td>The scale of all tiles. Can be used to increase or decrease the size of every tile</td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#tilescales">tileScales</a></td><td>Object</td><td>empty</td><td>Used by the &quot;Minimal&quot; tileset to scale all its tiles except the base terrain down. Overrides <code>tileScale</code> value for specified terrain</td></tr><tr><td><a href="./../Creating-a-custom-tileset.html#rulevariants">ruleVariants</a></td><td>Object</td><td>empty</td><td><a href="#layering-images">See here</a></td></tr></tbody></table><h3 id="layering-images" tabindex="-1">Layering images <a class="header-anchor" href="#layering-images" aria-label="Permalink to &quot;Layering images&quot;">​</a></h3><p>ruleVariants control substitutions when layering images for a tile, they are list looking like:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ruleVariants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Grassland+Forest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Grassland&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GrasslandForest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Plains+Forest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Plains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PlainsForest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Plains+Jungle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Plains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PlainsJungle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // . . .</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Each line means &quot;if the tile content is this... then combine the following png images&quot;. The key part follows a specific order and must match in its entirety, meaning &quot;Plains+Forest&quot; is not valid for &quot;Plains+Forest+Deer&quot;, and when it matches no other image layering is done except roads and units (I think - <em>WIP</em>).</p><p>When TileSetConfig&#39;s for the same Tileset are combined, for the first three properties the last mod wins, while ruleVariants are merged, meaning only an entry with the same key overwrites an earlier entry. (TODO)</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><p>Terrains, features, resources and improvements may list yield statistics. The statistics can be one of the following:</p><ul><li>production</li><li>food</li><li>gold</li><li>science</li><li>culture</li><li>happiness</li><li>faith</li></ul><h3 id="general-stat" tabindex="-1">General stat <a class="header-anchor" href="#general-stat" aria-label="Permalink to &quot;General stat&quot;">​</a></h3><p>If an object carries general stat(s), it contains any combination (or none) of the above stats, each mapping to a corresponding number [^1]. For Example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;improvement&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Quarry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><h3 id="specialized-stats" tabindex="-1">Specialized stats <a class="header-anchor" href="#specialized-stats" aria-label="Permalink to &quot;Specialized stats&quot;">​</a></h3><p>For specialized stats, they might come as sub-object in a named field. The sub-object contains any combination (or none) of the above stats, each mapping to a corresponding number [^1]. For Example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;improvement&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Quarry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;improvementStats&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;production&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span></code></pre></div><p>[^1]: The values are usually integers, though the underlying code supports floating point. The effects are, however, insufficiently tested and therefore -so far- using fractional stats is unsupported. Go ahead and thoroughly test that in a mod and help out with feedback 😁.</p>`,54)])])}const m=e(n,[["render",r]]);export{c as __pageData,m as default};
